1156	// graph builds one layer's dispatch sequence with a label per dispatch, and
1157	// is shared by Run and Profile so that what the profiler times is what a run
1158	// executes.
1159	func (g *MoEGPU) graph(layer int) ([]vk.MultiDispatch, []string, error) {
1160		if layer < 0 || layer >= len(g.layers) {
1161			return nil, nil, fmt.Errorf("llm: layer %d of %d", layer, len(g.layers))
1162		}
1163		c := g.cfg
1164		w := g.layers[layer]
1165		rv, _ := gemmVariantFor(g.router)
1166		bmUp, bmDown := moeBM(g.up), moeBM(g.down)
1167	
1168		base := push{
1169			Tokens: uint32(g.rows), NEmbd: uint32(c.NEmbd),
1170			LDA: uint32(g.lda), LDCtx: uint32(g.ldCtx),
1171			XnOff: g.hXn, QKVOff: g.aLogits, OutOff: g.aOut, GatedOff: g.aGated,
1172			MoEWeightOff: g.aWeights,
1173			// The used count in the low sixteen bits and the layer's bank index
1174			// in the high, because the push block is full at 64 uints and the
1175			// GEMM needs to know which buffer of the array it reads (L6a).
1176			MoEUsed: uint32(c.NExpertUsed) | uint32(w.bank)<<16,
1177			GateOff: noW,
1178		}
1179	
1180		var d []vk.MultiDispatch
1181		var kinds []string
1182		add := func(pipe, kind string, gx, gy uint32, pc push) {
1183			d = append(d, vk.MultiDispatch{Pipeline: g.pipes[pipe], GroupsX: gx, GroupsY: gy, PushConstants: pc.bytes()})
1184			kinds = append(kinds, kind)
1185		}
1186	
1187		// 1. The router, with the shared expert's gate as one more output column.
1188		//    At one token it is a split-K GEMV in two dispatches and at every
1189		//    other length the GEMM (L8d-3); both write the same f32 logits row.
1190		router := base
1191		router.OutOff, router.BOff = g.aLogits, w.router
1192		router.GemmM = uint32(roundUpInt(g.rows, rv.bm))
1193		router.GemmN, router.GemmK = uint32(g.routerN()), uint32(c.NEmbd)
1194		if ks := moeRouterSlabs(g.routerGemv); ks > 0 {
1195			router.GammaOff = g.aRouterPart
1196			add(fmt.Sprintf("router_%s", g.routerGemv), "router",
1197				uint32(ks), uint32(g.routerN()/16), router)
1198			add(fmt.Sprintf("router_%s_r", g.routerGemv), "router.sum",
1199				uint32(roundUpInt(g.routerN(), moeWave)/moeWave), 1, router)
1200		} else {
1201			add(string(g.router), "router", uint32(g.routerN()/attnBN),
1202				uint32(roundUpInt(g.rows, rv.bm)/rv.bm), router)
1203		}
1204	
1205		// 2. The softmax, the ten argmaxes, the normalise and the shared gate.
1206		route := base
1207		route.GemmN, route.GemmK = uint32(g.routerN()), uint32(c.NExpert)
1208		route.MoEPermOff = g.aPerm
1209		add("route", "route", uint32(g.rows), 1, route)
1210	
1211		// 3-4. The counting sort, and the tile schedules it implies. It runs
1212		//      twice because the two modes are cut to different row blocks and a
1213		//      tile list is only consistent with the permutation that outlives
1214		//      it — so both passes happen before either GEMM reads one.
1215		//
1216		//      **Unless the two row blocks are the same number**, which is every
1217		//      decode step: all six GEMV rungs cut their tile list to sixteen
1218		//      rows, so the second pass recomputes the first pass's permutation
1219		//      and emits the same records into a second buffer (L8e-3). Then
1220		//      there is one pass and `downTiles` points the down mode at the up
1221		//      mode's list.
1222		passes := []struct {
1223			off uint32
1224			bm  int
1225			lbl string
1226		}{{g.aTilesUp, bmUp, "perm.up"}}
1227		if bmDown != bmUp {
1228			passes = append(passes, struct {
1229				off uint32
1230				bm  int
1231				lbl string
1232			}{g.aTilesDown, bmDown, "perm.down"})
1233		}
1234		for _, t := range passes {
1235			p := base
1236			p.GemmK, p.GemmM, p.GemmN = uint32(c.NExpert), uint32(t.bm), uint32(g.pad())
1237			p.MoEPermOff, p.MoETileOff, p.MoEBOff2 = g.aPerm, t.off, g.aBook
1238			add("perm", t.lbl, 1, 1, p)
1239		}
1240	
1241		// 5. gate and up for every routed row, with the swiglu on the
1242		//    accumulators.
1243		up := base
1244		up.MoEPermOff, up.MoETileOff = g.aPerm, g.aTilesUp
1245		up.BOff, up.MoEBOff2 = w.gate, w.up
1246		up.CtxOff = g.hSwiglu
1247		up.GemmN, up.GemmK = uint32(c.FFNExpert), uint32(c.NEmbd)
1248		add(fmt.Sprintf("up_%s_%s", w.gateFmt, g.up), "up",
1249			uint32(c.FFNExpert/moeBNOf(g.up)), uint32(g.maxTiles(bmUp, g.rows)), up)
1250	
1251		// 6. down, weighted and scattered to its (token, slot).
1252		down := base
1253		down.MoEPermOff, down.MoETileOff = g.aPerm, g.downTiles()
1254		down.BOff = w.down
1255		down.CtxOff = g.hSwiglu
1256		down.GemmN, down.GemmK = uint32(c.NEmbd), uint32(c.FFNExpert)
1257		add(fmt.Sprintf("down_%s_%s", w.downFmt, g.down), "down",
1258			uint32(c.NEmbd/moeBNOf(g.down)), uint32(g.maxTiles(bmDown, g.rows)), down)
1259	
1260		// 7-8. The shared expert: the same two kernels over one group whose
1261		//      permutation is the identity, because it is the same shape as a
1262		//      routed expert and runs for every token.
1263		shUp := base
1264		shUp.MoEPermOff, shUp.MoETileOff = g.aPerm, g.aShTilesUp
1265		shUp.BOff, shUp.MoEBOff2 = w.shGate, w.shUp
1266		shUp.CtxOff = g.hSwiglu
1267		shUp.GemmN, shUp.GemmK = uint32(c.FFNShared), uint32(c.NEmbd)
1268		add(fmt.Sprintf("up_%s_%s", w.shGateFmt, g.shUp), "shexp.up",
1269			uint32(c.FFNShared/moeBNOf(g.shUp)), uint32(roundUpInt(g.rows, g.pad())/moeBM(g.shUp)), shUp)
1270	
1271		shDown := base
1272		shDown.MoEPermOff, shDown.MoETileOff = g.aPerm, g.aShTilesDown
1273		shDown.BOff = w.shDown
1274		shDown.CtxOff = g.hSwiglu
1275		shDown.GemmN, shDown.GemmK = uint32(c.NEmbd), uint32(c.FFNShared)
1276		add(fmt.Sprintf("down_%s_%s", w.shDownFmt, g.shDown), "shexp.down",
1277			uint32(c.NEmbd/moeBNOf(g.shDown)), uint32(roundUpInt(g.rows, g.pad())/moeBM(g.shDown)), shDown)
1278	
1279		// 9. `ffn_out`: the ten and the shared expert's, in slot order.
1280		add("combine", "combine", uint32(roundUpInt(c.NEmbd, moeCombineWG)/moeCombineWG), uint32(g.rows), base)
1281		return d, kinds, nil
1282	}
