1284	// Run executes one layer's block over whatever Upload left in the arenas.
1285	func (g *MoEGPU) Run(layer int) error {
1286		d, kinds, err := g.graph(layer)
1287		if err != nil {
1288			return err
1289		}
1290		// One command buffer for the whole block, not one a dispatch: a submit
1291		// and a fence wait is ~150 us here and a decode step is a batch of one,
1292		// so what the sequence costs is how many times it is handed over
1293		// (LLM.md L7c). And when the graph is recording a whole pass, not even
1294		// one a block (L7d).
1295		if g.rec.add(ownMoE, kinds, d) {
1296			return nil
1297		}
1298		if _, err := vk.DispatchMultiTimed(d, 1, 1, true); err != nil {
1299			return fmt.Errorf("llm: moe, %d dispatches (%v): %w", len(d), kinds, err)
1300		}
1301		return nil
1302	}
1303	
1304	// Profile times each dispatch on the GPU over iters back-to-back repetitions.
1305	//
1306	// Unlike the other four blocks, repeating a dispatch here does not warm
1307	// anything that matters: one layer's bank is **1.57 GB** against a 32 MiB
1308	// MALL, so the second repetition reads the weights as cold as the first.
1309	// What repetition does hide is the host-side staging, which is the point.
1310	func (g *MoEGPU) Profile(layer, iters int) ([]Stage, error) {
1311		if iters <= 0 {
1312			iters = 1
1313		}
1314		d, kinds, err := g.graph(layer)
1315		if err != nil {
1316			return nil, err
1317		}
1318		out := make([]Stage, 0, len(d))
1319		for i := range d {
1320			dur, err := vk.DispatchMultiTimed(d[i:i+1], 1, uint32(iters), true)
1321			if err != nil {
1322				return out, fmt.Errorf("llm: moe dispatch %d (%s): %w", i, kinds[i], err)
1323			}
1324			out = append(out, Stage{Kind: kinds[i], GPU: dur / time.Duration(iters)})
1325		}
1326		return out, nil
1327	}
1328	
1329	// ProfileSweep times each kind of dispatch across every staged layer.
1330	func (g *MoEGPU) ProfileSweep(iters int) ([]Stage, error) {
1331		if iters <= 0 {
1332			iters = 1
1333		}
1334		_, kinds, err := g.graph(0)
1335		if err != nil {
1336			return nil, err
1337		}
1338		out := make([]Stage, 0, len(kinds))
1339		for k := range kinds {
1340			var total time.Duration
1341			for l := range g.layers {
1342				d, _, err := g.graph(l)
1343				if err != nil {
1344					return nil, err
1345				}
1346				dur, err := vk.DispatchMultiTimed(d[k:k+1], 1, uint32(iters), true)
1347				if err != nil {
1348					return out, fmt.Errorf("llm: %s sweep, layer %d: %w", kinds[k], l, err)
1349				}
1350				total += dur
1351			}
1352			out = append(out, Stage{Kind: kinds[k], GPU: total / time.Duration(len(g.layers)*iters)})
1353		}
1354		return out, nil
1355	}
