1445	// Swiglu is `ffn_moe_swiglu` in permutation order, [rows][ffn], and
1446	// Unpermute turns it back into the reference's [T][used][ffn].
1447	func (g *MoEGPU) Swiglu() []float32 {
1448		n := g.Rows()
1449		raw := g.hbuf.ReadUint16At(int(g.hSwiglu), n*g.ldCtx)
1450		out := make([]float32, n*g.cfg.FFNExpert)
