1472	// Unpermute reads a [rows][width] tensor in permutation order back into the
1473	// reference's [T][used][width], which is what a tensor comparison needs. The
1474	// shared expert's slot is dropped, because the reference names that tensor
1475	// separately.
1476	func (g *MoEGPU) Unpermute(src []float32, width int) []float32 {
1477		used := g.cfg.NExpertUsed
1478		slots := used + 1
1479		inv := g.InvPerm()
1480		out := make([]float32, g.rows*used*width)
1481		for t := 0; t < g.rows; t++ {
1482			for k := 0; k < used; k++ {
1483				r := int(inv[t*slots+k])
1484				copy(out[(t*used+k)*width:(t*used+k+1)*width], src[r*width:(r+1)*width])
1485			}
1486		}
1487		return out
1488	}
