1490	// Weighted is `ffn_moe_weighted` beside `ffn_shexp_gated`: [T][used+1][nEmbd],
1491	// the down projection's output times its slot's weight.
1492	//
1493	// Neither the multiply nor this layout exists on the device — the down
1494	// projection stores whole cooperative-matrix fragments in permutation order
1495	// and the combine carries the weight — so this is the reference's tensor
1496	// reconstructed from the two things that do exist, which is what a comparison
1497	// against llama.cpp's graph needs and what a kernel should not be made to
1498	// produce.
1499	func (g *MoEGPU) Weighted() []float32 {
1500		c := g.cfg
1501		slots := c.NExpertUsed + 1
1502		raw := g.abuf.ReadFloat32At(int(g.aGated), g.Rows()*c.NEmbd)
1503		w := g.Weights()
1504		inv := g.InvPerm()
1505		out := make([]float32, g.rows*slots*c.NEmbd)
1506		for t := 0; t < g.rows; t++ {
1507			for k := 0; k < slots; k++ {
1508				r := int(inv[t*slots+k])
1509				wt := w[t*slots+k]
1510				src := raw[r*c.NEmbd : (r+1)*c.NEmbd]
1511				dst := out[(t*slots+k)*c.NEmbd:]
1512				for j, v := range src {
1513					dst[j] = v * wt
1514				}
1515			}
1516		}
1517		return out
1518	}
1519	
1520	// Out is `ffn_out`, [T][nEmbd] — the block's output.
1521	func (g *MoEGPU) Out() []float32 {
1522		return g.abuf.ReadFloat32At(int(g.aOut), g.rows*g.cfg.NEmbd)
1523	}
