1528			if p != nil {
1529				p.Destroy()
1530			}
1531		}
1532		g.pipes = nil
1533		for _, m := range g.mods {
1534			m.Destroy()
1535		}
1536		g.mods = nil
1537		for _, b := range append([]*vk.Buffer{g.wbuf, g.abuf, g.hbuf, g.bank}, g.qbufs...) {
1538			if b != nil {
1539				b.Destroy()
1540			}
1541		}
1542		g.wbuf, g.abuf, g.hbuf, g.bank, g.qbufs = nil, nil, nil, nil, nil
1543	}
