1545	// Schedule reports what a rung's tile list costs: how many (expert, row
1546	// block) records it holds and how many rows those records execute against
1547	// how many are real. The gap is L5a-4's distribution paying for a static
1548	// tiling — 273 of the 274 experts a 512-token ubatch touches have fewer than
1549	// 19 rows, so most tiles are mostly padding — and it is what says whether a
1550	// wide row block is reuse or waste.
1551	func (g *MoEGPU) Schedule(k MoEKernel) (tiles, executed, real int) {
1552		bm, pad := moeBM(k), g.pad()
1553		for _, c := range g.Counts() {
1554			padded := roundUpInt(int(c), pad)
1555			tiles += padded / bm
1556			executed += padded
1557			real += int(c)
1558		}
1559		return tiles, executed, real
1560	}
1561	
1562	// Touched is how many of the experts this prompt's routing reaches. L5a-4
1563	// measured 274 of 512 at a 512-token ubatch and 435 at 4096; it is a fact
1564	// about the prompt, and it is what decides how much of the bank a run reads.
1565	func (g *MoEGPU) Touched() int {
1566		n := 0
1567		for _, c := range g.Counts() {
1568			if c > 0 {
1569				n++
1570			}
1571		}
1572		return n
1573	}
1574	
1575	// ExpertBytes is how many bytes of the quantised bank one expert costs, in
1576	// the checkpoint's own formats: the gate/up pair a swiglu tile reads, and the
1577	// down matrix a down tile reads. The whole bank divided by the expert count,
1578	// so it follows the layer's formats rather than assuming them.
1579	func (g *MoEGPU) ExpertBytes(layer int) (upPair, down int) {
1580		c := g.cfg
1581		w := g.layers[layer]
1582		rowBytes := func(f moeFmt, k int) int {
1583			switch f {
1584			case fmtQ4K:
1585				return k / 256 * 144
1586			case fmtQ5K:
1587				return k / 256 * 176
1588			case fmtQ51:
1589				return k / 32 * 24
1590			}
1591			return k / 32 * 34
1592		}
1593		upPair = c.FFNExpert * (rowBytes(w.gateFmt, c.NEmbd) + rowBytes(w.upFmt, c.NEmbd))
1594		down = c.NEmbd * rowBytes(w.downFmt, c.FFNExpert)
1595		return upPair, down
1596	}
1597	
1598	// SharedBytes is the same for the always-on expert, which runs for every
1599	// token and is the same shape as a routed one.
1600	func (g *MoEGPU) SharedBytes(layer int) (upPair, down int) {
1601		c := g.cfg
1602		upPair = c.FFNShared * (c.NEmbd / 32 * 34) * 2
1603		down = c.NEmbd * (c.FFNShared / 32 * 34)
1604		return upPair, down
1605	}
1606	
1607	// Formats names the layer's three routed banks, which decide which build of
1608	// the grouped GEMM runs and how many bytes an expert costs.
1609	func (g *MoEGPU) Formats(layer int) (gate, up, down string) {
1610		w := g.layers[layer]
1611		return w.gateFmt.String(), w.upFmt.String(), w.downFmt.String()
1612	}
1613	
1614	// InPort is the block's input as the router's and every routed tile's A
1615	// operand wants it: fp16 [T][lda], `hc_mixed` narrowed. The row count is the
1616	// widest row block a rung uses, because the grouped GEMM has no bounds check.
1617	func (g *MoEGPU) InPort() Port {
1618		return Port{Buf: g.hbuf, Off: g.hXn, Stride: g.lda, Width: g.cfg.NEmbd,
1619			Rows: roundUpInt(g.rows, moeBMMax), Half: true}
1620	}
1621	
1622	// OutPort is the block's output, `ffn_out`: fp32 [T][nEmbd].
1623	func (g *MoEGPU) OutPort() Port {
1624		return Port{Buf: g.abuf, Off: g.aOut, Stride: g.cfg.NEmbd, Width: g.cfg.NEmbd}
1625	}
1626	
1627	// Resize sets the length of the run and writes the shared expert's own
1628	// permutation and schedule, which are the identity over the run's tokens and
1629	// so stay host-side however the input arrives.
1630	func (g *MoEGPU) Resize(nTok int) error {
1631		if nTok <= 0 || nTok > g.tokens {
1632			return fmt.Errorf("llm: %d tokens, staged for %d", nTok, g.tokens)
1633		}
1634		if !g.autoPlan {
1635			if err := moeCheckGemv(g.up, g.down, nTok); err != nil {
1636				return err
1637			}
1638			if err := moeCheckGemv(g.shUp, g.shDown, nTok); err != nil {
1639				return err
1640			}
1641		}
1642		g.rows = nTok
1643		if g.autoPlan {
1644			g.router = GEMMKernelFor(nTok)
1645			g.up, g.down, g.routerGemv = g.moePlan(nTok)
1646			g.shUp, g.shDown = g.moeSharedPlan(nTok)
1647		}
1648		g.syncShared()
1649		return nil
1650	}

